import{_ as s,l as i,o as a,c as l,v as t,p as c,x as o,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"WebSocket","description":"","frontmatter":{"title":"WebSocket","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/websocket.md","filePath":"cs/websocket.md","lastUpdated":1789023840000}'),h={name:"cs/websocket.md"};function S(T,e,b,_,k,u){const r=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to &quot;WebSocket&quot;">​</a></h1><div class="epigraph"><p>HTTP 升级成一条全双工消息帧通道，不再一请求一响应；掩码与关闭握手是协议，不是套接字 API。</p><footer>—— 据 RFC 6455 The WebSocket Protocol 整理</footer></div><p><a href="/cs/http11-persistent-chunked">持久连接</a> 仍是请求–响应。<a href="/cs/content-negotiation">上一课</a> 不给服务器随时推字节。缺口是 <strong>WebSocket</strong>：Upgrade、帧、掩码。本课不把 SSE 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>聊天、协同编辑要服务器随时推。轮询浪费、长轮询半吊。WS：HTTP/1.1 <code>Upgrade: websocket</code> 握手（H2 有扩展），之后二进制帧：opcode、载荷、客户端掩码防代理缓存污染。仍跑在 TCP（或 H2 流）上，HOL 与无线掉线仍在。应用子协议在握手 Sec-WebSocket-Protocol。</p><p>不要把 WS 写成 UDP。</p><p><span class="marginnote">RFC 6455。wss 走 TLS。本课不把每 opcode 背完。</span></p><h3 id="升级后是帧协议" tabindex="-1">升级后是帧协议 <a class="header-anchor" href="#升级后是帧协议" aria-label="Permalink to &quot;升级后是帧协议&quot;">​</a></h3><p>全双工，客户端掩码。代理必须理解 Upgrade。连接状态要求粘滞。不是 UDP，也不是 REST。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：HTTP 握手 → 切换 → 双向帧。对照 QUIC DATAGRAM/WebTransport 点名。与 Cookie：握手仍带 Cookie 做会话。</p>',11)),(a(),c(d,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22HTTP%20Upgrade%22%5D%20--%3E%20WS%5B%22WebSocket%20%E5%B8%A7%22%5D%0A%20%20WS%20--%3E%20C2S%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E6%8E%A9%E7%A0%81%22%5D%0A%20%20WS%20--%3E%20S2C%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E6%8E%A8%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>负载均衡要粘会话，因状态在连接上——后课 L4/L7。反向代理须理解 Upgrade，否则 400。心跳：ping/pong 帧，比 TCP keepalive 更适合应用。TSO 对小消息帮助有限。</p><p>安全：跨站 WS 要 Origin 检查，不写利用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 RFC 8441 的 H2 扩展细节全文。SSE 与服务器推送是下一课。后课默认：WS 是升级后的全双工帧；语义不是 REST。</p><p>防火墙只懂 GET 文件时 Upgrade 会被剥。</p><p>上一课留下的缺口在本课收口；「WebSocket」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/sse-server-push">SSE 与服务器推送</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>握手用 HTTP 升级，之后是帧协议。</li><li>全双工，客户端帧掩码。</li><li>连接状态要求粘滞与代理支持。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 6455。</li></ul>',10))])}const A=s(h,[["render",S]]);export{m as __pageData,A as default};
